import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Async Thunk to fetch dashboard data (e.g., event count, user count, feedback count)
export const fetchDashboardData = createAsyncThunk(
  'admin/fetchDashboardData',
  async (_, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/admin/dashboard', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return response.data; // events, users, feedback
    } catch (err) {
      return rejectWithValue('Failed to load dashboard data');
    }
  }
);

// Async Thunk to fetch users
export const fetchUsers = createAsyncThunk(
  'admin/fetchUsers',
  async (_, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/admin/users', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return response.data; // Return the list of users
    } catch (err) {
      return rejectWithValue('Failed to fetch users');
    }
  }
);

// Async Thunk to delete a user
export const deleteUser = createAsyncThunk(
  'admin/deleteUser',
  async (userId, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem('token');
      await axios.delete(`http://localhost:5000/api/admin/users/${userId}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return userId; // Return the deleted user's ID
    } catch (err) {
      return rejectWithValue('Failed to delete user');
    }
  }
);

// Admin Slice
const adminSlice = createSlice({
  name: 'admin',
  initialState: {
    eventCount: 0,
    userCount: 0,
    feedbackCount: 0,
    users: [],
    loading: false,
    error: '',
  },
  reducers: {},
  extraReducers: (builder) => {
    // Handle fetchDashboardData
    builder
      .addCase(fetchDashboardData.pending, (state) => {
        state.loading = true;
        state.error = '';
      })
      .addCase(fetchDashboardData.fulfilled, (state, action) => {
        const { events, users, feedback } = action.payload;
        state.eventCount = events;
        state.userCount = users;
        state.feedbackCount = feedback;
        state.loading = false;
      })
      .addCase(fetchDashboardData.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });

    // Handle fetchUsers
    builder
      .addCase(fetchUsers.pending, (state) => {
        state.loading = true;
        state.error = '';
      })
      .addCase(fetchUsers.fulfilled, (state, action) => {
        state.users = action.payload;
        state.loading = false;
      })
      .addCase(fetchUsers.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });

    // Handle deleteUser
    builder
      .addCase(deleteUser.pending, (state) => {
        state.loading = true;
        state.error = '';
      })
      .addCase(deleteUser.fulfilled, (state, action) => {
        state.users = state.users.filter((user) => user.id !== action.payload);
        state.loading = false;
      })
      .addCase(deleteUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });
  },
});

export default adminSlice.reducer;



